USE HealthCarePortalDB;
GO
INSERT dbo.Appointments (AppointmentCode,PatientId,DoctorId,DepartmentId,AppointmentDate,StartTime,EndTime,ReasonForVisit,AppointmentStatus,BookingSource,ConsultationFee,ReceptionistId)
SELECT CONCAT(N'APT',RIGHT(CONCAT(N'000',v.N),3)),p.PatientId,d.DoctorId,sp.DepartmentId,DATEADD(DAY,v.DayOffset,CONVERT(date,GETDATE())),v.StartTime,DATEADD(MINUTE,30,v.StartTime),v.Reason,v.Status,v.Source,d.ConsultationFee,r.ReceptionistId
FROM (VALUES
(1,1,1,1,0,'09:00',N'Annual cardiac review',N'Pending',N'Patient'),(2,2,1,1,1,'09:30',N'Chest discomfort',N'Confirmed',N'Receptionist'),(3,3,2,2,2,'10:00',N'Headache review',N'Checked-In',N'Patient'),(4,4,2,2,3,'10:30',N'Migraine symptoms',N'In Consultation',N'Patient'),(5,5,3,3,4,'09:00',N'Knee pain',N'Completed',N'Receptionist'),(6,6,3,3,5,'09:30',N'Follow-up',N'Cancelled',N'Patient'),(7,7,4,6,6,'10:00',N'Fever',N'No Show',N'Patient'),(8,8,4,6,7,'10:30',N'Wellness visit',N'Completed',N'Receptionist'),(9,9,5,9,8,'09:00',N'Tooth pain',N'Completed',N'Patient'),(10,10,5,9,9,'09:30',N'Cleaning',N'Pending',N'Patient'),(11,1,1,1,10,'10:00',N'Cardiac consultation',N'Confirmed',N'Patient'),(12,2,2,2,11,'09:00',N'Neurological review',N'Completed',N'Patient'),(13,3,3,3,12,'10:30',N'Back pain',N'Confirmed',N'Receptionist'),(14,4,4,6,13,'09:00',N'General checkup',N'Pending',N'Patient'),(15,5,5,9,14,'10:00',N'Dental review',N'Completed',N'Patient'),(16,6,1,1,15,'10:30',N'Blood pressure',N'Confirmed',N'Patient'),(17,7,2,2,16,'09:30',N'Dizziness',N'Pending',N'Patient'),(18,8,3,3,17,'10:00',N'Joint pain',N'Completed',N'Receptionist'),(19,9,4,6,18,'09:30',N'Health screening',N'Confirmed',N'Patient'),(20,10,5,9,19,'10:30',N'Tooth sensitivity',N'Pending',N'Patient')) v(N,PatientNo,DoctorNo,DepartmentNo,DayOffset,StartTime,Reason,Status,Source)
JOIN dbo.Patients p ON p.PatientCode=CONCAT(N'P',RIGHT(CONCAT(N'000',v.PatientNo),4)) JOIN dbo.Doctors d ON d.DoctorCode=CONCAT(N'DR',RIGHT(CONCAT(N'000',v.DoctorNo),4)) JOIN dbo.Specializations sp ON sp.SpecializationId=d.SpecializationId JOIN dbo.Receptionists r ON r.EmployeeCode=N'EMP0001';
GO
